  7	/**
  8	 * Immutable compiled representation of a pattern for Knuth-Morris-Pratt searches.
  9	 */
 10	public final class KmpPattern {
 11	    private final String value;
 12	    private final int[] longestPrefixSuffix;
 13	
 14	    private KmpPattern(String value, int[] longestPrefixSuffix) {
 15	        this.value = value;
 16	        this.longestPrefixSuffix = longestPrefixSuffix;
 17	    }
 18	
 19	    public static KmpPattern compile(CharSequence pattern) {
 20	        Objects.requireNonNull(pattern, "pattern must not be null");
 21	
 22	        String patternValue = pattern.toString();
 23	
 24	        if (patternValue.isEmpty()) {
 25	            throw new IllegalArgumentException("pattern must not be empty");
 26	        }
 27	
 28	        return new KmpPattern(patternValue, buildLongestPrefixSuffixTable(patternValue));
 29	    }
 30	
 31	    public String value() {
 32	        return value;
 33	    }
 34	
 35	    public KmpMatchIterator matchIteratorIn(CharSequence text) {
 36	        validateText(text);
 37	        return new KmpMatchIterator(value, longestPrefixSuffix, text);
 38	    }
 39	
 40	    public KmpMatchResult analyzeIn(CharSequence text) {
 41	        List<Integer> matches = new ArrayList<>();
 42	        KmpMatchIterator iterator = matchIteratorIn(text);
 43	        iterator.forEachRemaining((int matchIndex) -> matches.add(matchIndex));
 44	
 45	        if (matches.isEmpty()) {
 46	            return KmpMatchResult.noMatches();
 47	        }
 48	
 49	        return KmpMatchResult.from(matches);
 50	    }
 51	
 52	    public List<Integer> findMatchesIn(CharSequence text) {
 53	        return analyzeIn(text).matchIndices();
 54	    }
 55	
 56	    public OptionalInt findFirstIn(CharSequence text) {
 57	        KmpMatchIterator iterator = matchIteratorIn(text);
 58	        return iterator.hasNext() ? OptionalInt.of(iterator.nextInt()) : OptionalInt.empty();
 59	    }
 60	
 61	    public int countMatchesIn(CharSequence text) {
 62	        int matchCount = 0;
 63	        KmpMatchIterator iterator = matchIteratorIn(text);
 64	
 65	        while (iterator.hasNext()) {
 66	            iterator.nextInt();
 67	            matchCount++;
 68	        }
 69	
 70	        return matchCount;
 71	    }
 72	
 73	    public boolean occursIn(CharSequence text) {
 74	        return matchIteratorIn(text).hasNext();
 75	    }
 76	
 77	    public void forEachMatchIn(CharSequence text, IntConsumer matchConsumer) {
 78	        Objects.requireNonNull(matchConsumer, "matchConsumer must not be null");
 79	        matchIteratorIn(text).forEachRemaining(matchConsumer);
 80	    }
 81	
 82	    static int[] buildLongestPrefixSuffixTable(String pattern) {
 83	        int[] table = new int[pattern.length()];
 84	        int prefixLength = 0;
 85	        int currentIndex = 1;
 86	
 87	        while (currentIndex < pattern.length()) {
 88	            if (pattern.charAt(currentIndex) == pattern.charAt(prefixLength)) {
 89	                table[currentIndex] = ++prefixLength;
 90	                currentIndex++;
 91	                continue;
 92	            }
 93	
 94	            if (prefixLength > 0) {
 95	                prefixLength = table[prefixLength - 1];
 96	            } else {
 97	                table[currentIndex] = 0;
 98	                currentIndex++;
 99	            }
100	        }
101	
102	        return table;
103	    }
104	
105	    private void validateText(CharSequence text) {
106	        Objects.requireNonNull(text, "text must not be null");
107	    }
108	}

