  6	public final class KmpSearchSelfTest {
  7	
  8	    private KmpSearchSelfTest() {
  9	    }
 10	
 11	    public static void main(String[] args) {
 12	        assertEquals(List.of(0, 9, 12), KmpSearch.search("aaba", "aabaacaadaabaaba"), "basic search");
 13	        assertEquals(List.of(0, 1, 2), KmpSearch.search("aa", "aaaa"), "overlapping matches");
 14	        assertEquals(List.of(), KmpSearch.search("xyz", "aaaa"), "no matches");
 15	        assertEquals(List.of(), KmpSearch.search("longer-pattern", "short"), "pattern longer than text");
 16	        assertAnalysis(KmpSearch.analyze("aaba", "aabaacaadaabaaba"), List.of(0, 9, 12), "analysis through facade");
 17	        assertEquals(List.of(0, 2), collectMatches(KmpSearch.matchIterator("aba", "ababa")), "iterator through facade");
 18	        assertEquals(OptionalInt.of(2), KmpSearch.findFirst("aaba", "xxaabaacaadaabaaba"), "first match through facade");
 19	        assertEquals(3, KmpSearch.countMatches("aa", "aaaa"), "count matches through facade");
 20	        assertTrue(KmpSearch.contains("aba", "xxabaxx"), "contains through facade");
 21	        assertFalse(KmpSearch.contains("aba", "xxxx"), "contains through facade negative");
 22	        assertEquals(List.of(0, 2), collectMatches("aba", "ababa"), "forEachMatch through facade");
 23	
 24	        KmpPattern compiledPattern = KmpPattern.compile("aba");
 25	        assertEquals("aba", compiledPattern.value(), "compiled pattern preserves source value");
 26	        assertAnalysis(compiledPattern.analyzeIn("ababa"), List.of(0, 2), "compiled pattern analysis");
 27	        assertEquals(List.of(0, 2), collectMatches(compiledPattern.matchIteratorIn("ababa")), "pattern iterator search");
 28	        assertEquals(List.of(0, 2), compiledPattern.findMatchesIn("ababa"), "compiled pattern search");
 29	        assertEquals(List.of(0, 2), compiledPattern.findMatchesIn(new StringBuilder("ababa")), "char sequence search");
 30	        assertEquals(OptionalInt.of(0), compiledPattern.findFirstIn("ababa"), "first match search");
 31	        assertEquals(OptionalInt.empty(), compiledPattern.findFirstIn("xxxx"), "first match no result");
 32	        assertEquals(2, compiledPattern.countMatchesIn("ababa"), "count matches");
 33	        assertTrue(compiledPattern.occursIn("xxabaxx"), "occursIn should detect matches");
 34	        assertFalse(compiledPattern.occursIn("xxxx"), "occursIn should reject missing matches");
 35	        assertEquals(List.of(0, 2), collectMatches(compiledPattern, "ababa"), "forEachMatchIn enumerates matches");
 36	        assertThrows(UnsupportedOperationException.class, () -> compiledPattern.findMatchesIn("ababa").add(99), "match list is immutable");
 37	
 38	        assertThrows(IllegalArgumentException.class, () -> KmpPattern.compile(""), "empty pattern rejected");
 39	        assertThrows(NullPointerException.class, () -> KmpPattern.compile(null), "null pattern rejected");
 40	        assertThrows(NullPointerException.class, () -> compiledPattern.findMatchesIn(null), "null text rejected");
 41	        assertThrows(NullPointerException.class, () -> compiledPattern.matchIteratorIn(null), "null iterator text rejected");
 42	        assertThrows(NullPointerException.class, () -> compiledPattern.forEachMatchIn("ababa", null), "null match consumer rejected");
 43	        assertThrows(java.util.NoSuchElementException.class, () -> exhaustedIterator(compiledPattern).nextInt(), "iterator rejects nextInt when exhausted");
 44	    }
