 46	    private static void assertAnalysis(KmpMatchResult result, List<Integer> expectedMatches, String scenario) {
 47	        assertEquals(expectedMatches, result.matchIndices(), scenario + " indices");
 48	        assertEquals(expectedMatches.size(), result.count(), scenario + " count");
 49	        assertEquals(!expectedMatches.isEmpty(), result.hasMatches(), scenario + " presence");
 50	        assertEquals(toOptional(expectedMatches.isEmpty() ? null : expectedMatches.get(0)), result.firstMatch(), scenario + " first");
 51	        assertEquals(
 52	                toOptional(expectedMatches.isEmpty() ? null : expectedMatches.get(expectedMatches.size() - 1)),
 53	                result.lastMatch(),
 54	                scenario + " last");
 55	        assertEquals(expectedMatches.toString(), result.toString(), scenario + " string");
 56	    }
