 58	    private static List<Integer> collectMatches(KmpPattern pattern, CharSequence text) {
 59	        List<Integer> matches = new java.util.ArrayList<>();
 60	        pattern.forEachMatchIn(text, matches::add);
 61	        return List.copyOf(matches);
 62	    }
