 64	    private static List<Integer> collectMatches(CharSequence pattern, CharSequence text) {
 65	        List<Integer> matches = new java.util.ArrayList<>();
 66	        KmpSearch.forEachMatch(pattern, text, matches::add);
 67	        return List.copyOf(matches);
 68	    }
