 70	    private static List<Integer> collectMatches(KmpMatchIterator iterator) {
 71	        List<Integer> matches = new java.util.ArrayList<>();
 72	
 73	        while (iterator.hasNext()) {
 74	            matches.add(iterator.nextInt());
 75	        }
 76	
 77	        return List.copyOf(matches);
 78	    }
