 84	    private static KmpMatchIterator exhaustedIterator(KmpPattern pattern) {
 85	        KmpMatchIterator iterator = pattern.matchIteratorIn("xxxx");
 86	        assertFalse(iterator.hasNext(), "iterator should be exhausted");
 87	        return iterator;
 88	    }
