 90	    private static void assertEquals(Object expected, Object actual, String scenario) {
 91	        if (!expected.equals(actual)) {
 92	            throw new AssertionError(scenario + ": expected " + expected + " but got " + actual);
 93	        }
 94	    }
 95	
 96	    private static void assertTrue(boolean condition, String scenario) {
 97	        if (!condition) {
 98	            throw new AssertionError(scenario);
 99	        }
100	    }
101	
102	    private static void assertFalse(boolean condition, String scenario) {
103	        assertTrue(!condition, scenario);
104	    }
