106	    private static void assertThrows(
107	            Class<? extends Throwable> expectedType,
108	            ThrowingRunnable action,
109	            String scenario) {
110	        try {
111	            action.run();
112	        } catch (Throwable thrown) {
113	            if (expectedType.isInstance(thrown)) {
114	                return;
115	            }
116	
117	            throw new AssertionError(
118	                    scenario + ": expected " + expectedType.getSimpleName()
119	                            + " but got " + thrown.getClass().getSimpleName(),
120	                    thrown);
121	        }
122	
123	        throw new AssertionError(scenario + ": expected " + expectedType.getSimpleName());
124	    }
